%[text] # Vector Demo
%[text] A notation convention
%[text] - Scalars are lower case: `x`
%[text] - Vectors (1-D arrays) are double letters: `xx`
%[text] - Matrices (2-D arrays) are capitals: `X` \
%[text] ## Creation
%[text] As an vector with step size = 1
xx = 1:5  %[output:039cc8d0]
ss =size(xx) %[output:76758e5e]
%%
%[text] As a list with step size ~= 1
yy = 1:3:10 %[output:0722a53a]
%%
%[text] As an N-by-1 column of zeros
zz = zeros(5,1) %[output:732dec18]
zz = zeros(5,5) %[output:77129066]
%%
%[text] As a 1-by-N row of ones
oo  = ones(1,5) %[output:7eaa5249]
ff = 5*ones(1,5) %[output:59cacf70]
%%
%[text] A vector (1-by-N row) of psuedorandom numbers
rr = rand(1,5) %[output:41895ce9]
%%
%[text] Manually, as a row vector, with and without commas.
mm = [5 3.1 9.8 -2]

nn = [5, 3.1, 9.8, -2]
%%
%[text] Manually as a column vector
cc = [5; 3.1; 9.8; -2;] %[output:2fcb07b0]

cc = [5 %[output:group:792256c2] %[output:1230b716]
    3.1 %[output:1230b716]
    9.8] %[output:group:792256c2] %[output:1230b716]
% As a column using transpose
dd = [5 3.1 9.8 -2]' %[output:5f7010ea]
%%
%[text] Linear spacing from A to B with N elements
ll = linspace(0, 1, 101) %[output:55425afb]
mm = 0:0.5:1 %[output:504934b6]
%[text] Logrithmic spacing from 10^A to 10^B with N elements
pp = logspace(-2, 2, 5) %[output:84ce98bd]
%%
%[text] ### Exercises
%[text] Find a comand to create the following vectors
%[text] ![](text:image:2d13)
42*ones(1,4)
%[text] ![](text:image:2b40)

%[text] ![](text:image:1e89)
%[text] ![](text:image:1db5)

%[text] ![](text:image:6c4a)

%%
%[text] ## Indexing and Slicing
%[text] Given a vector...
aa = 10:10:100 %[output:4feda9c5]
%%
%[text] Access an element by its index
aa(4) %[output:8b9ef534]
aa_4thelelment = aa(4) %[output:2cb0da64]
aa(5) = 3.14 %[output:1f7cdceb]

%%
%[text] Slice a vector with a vector of indices
aa(1:3) %[output:93548efd]
%%
aa(8:end) %[output:9bd20c68]
aa(end-3:end) %[output:8d37d111]
%%
aa([3 5 7]) %[output:436b8e3d]
%%
%[text] Modifying an element
aa(3) = 0
%%
%[text]  or elements
aa([1 5]) = -1
aa([2 4]) = [-2 -3]
%%
%[text] ### Exercises
%[text] Given `bb`, extract all the elements in odd-numbered positions.
bb = 1:9
b_slice = bb([1,3,5,7])
bb

bb([1,3,5,7]) = -1
%[text] Given `cc` , using indexes, create a new vector that reverses the order of the elements
cc = [5 10 15 20]
size(cc,2)
c_rev = [];
for ii = 1:size(cc, 2)
    disp(cc(ii))
end

c_rev = [cc(end) cc(end-1) cc(end-2)]
c_ref = cc(end:-1:1)
%%
%[text] ## Array vs Matrix Operations
%[text] ![](text:image:5479)
%[text] [Link](https://www.mathworks.com/help/matlab/matlab_prog/array-vs-matrix-operations.html)
%[text] For now we want to use only element-wise array operations by prepending the math symbol with a period.
aa = [1 2] %[output:517724d3]
%[text] Addition/Subtraction
bb = aa+10 %[output:7ff67654]
cc = aa-bb %[output:2d6bbe84]
%%
%[text] Multiplication/Division
%[text] Multiply by a scalar
aa %[output:59195731]
dd = aa*0.1 %[output:110fa124]
%[text] Element-wise multiplication
dd %[output:05990d26]
aa %[output:0fb2194a]
aa %[output:57a46294]
dd %[output:2a1d2978]
ee = dd.*aa %[output:5c74e66f]
%[text] but this throws an errror!
%[text] 
dd = ee/aa %[output:26afd6cd]
%%
%[text] Exponents
%[text] Scalar exponent
ff = [1 2 4];
gg = ff.^2 %[output:8df892c1]
%[text] Element-wise exponent
gg = [-1 1 -1];
hh = ff.^gg %[output:940eaabe]
%[text] but this throws an error!
%[text] ![](text:image:63e4)
%%
%[text] ### Idiom: Plotting a 2D Function with Vectors
%[text] Model: Plot the function
%[text] $y(x) = x \\, sin(x)$
%[text] for  $0 \\leq x \\leq 2 \\pi$
% Define x values using linspace
xx = linspace(0, 2*pi, 100) %[output:96ebe2f0]

% Compute y using element-wise operations (note the .*)
yy = xx .* sin(xx) %[output:1a6c95cb]

% Plot
plot(xx, yy, '-') %[output:4f7009c9]
xlabel('x') %[output:4f7009c9]
ylabel('y') %[output:4f7009c9]
title('Example: y(x) = x .* sin(x)') %[output:4f7009c9]
grid on %[output:4f7009c9]
%%
%[text] ### Growing an array
% Make an array with one element
clear aa
aa = 10 %[output:56d5ee5c]
%%

% Grow the array one element at a time
for ii = 2:10
    aa(ii) = aa(ii-1)*0.9;
end
plot(aa, "r--o") %[output:2d507dd8]
aa(15) = 3.14159 %[output:7cb9518c]


